import { Image } from 'expo-image';
import { BRAND_NAME } from '@dispatcher/shared';
import { useTheme } from '@/lib/theme';

// Generated by `npm run brand:assets` from packages/design-tokens/brand/.
const LOGO_ON_DARK = require('@/assets/logo-on-dark.png');
const LOGO_ON_LIGHT = require('@/assets/logo-on-light.png');
const ASPECT = 960 / 506;

/** Full HaulGenius logotype; picks the variant that reads on the current theme. */
export function BrandLogo({ width = 200 }: { width?: number }) {
  const darkBackground = useTheme().statusBarStyle === 'light';
  return (
    <Image
      source={darkBackground ? LOGO_ON_DARK : LOGO_ON_LIGHT}
      style={{ width, height: width / ASPECT }}
      contentFit="contain"
      accessibilityRole="image"
      accessibilityLabel={BRAND_NAME}
    />
  );
}
